def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None

    decrease = old - new
    value = (decrease / old) * 100

    return {
        "value": value,
        "trace": {
            "old": old,
            "new": new,
            "decrease": decrease,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
